"use strict";(self.webpackChunkdata_shield_docs=self.webpackChunkdata_shield_docs||[]).push([["1073"],{8992(e,a,t){t.r(a),t.d(a,{metadata:()=>n,default:()=>p,frontMatter:()=>s,contentTitle:()=>r,toc:()=>d,assets:()=>l});var n=JSON.parse('{"id":"features/platform-admin-portal","title":"Feature: platform admin portal","description":"Every organization that signs up gets its own isolated workspace \u2014 its own","source":"@site/docs/features/platform-admin-portal.md","sourceDirName":"features","slug":"/features/platform-admin-portal","permalink":"/data-shield-docs/features/platform-admin-portal","draft":false,"unlisted":false,"editUrl":"https://github.com/DataShield-sp18/data-shield-docs/tree/main/docs/features/platform-admin-portal.md","tags":[],"version":"current","frontMatter":{},"sidebar":"docsSidebar","previous":{"title":"Feature: job-completion notifications","permalink":"/data-shield-docs/features/notifications"},"next":{"title":"XGBoost medical-code-family classifier","permalink":"/data-shield-docs/ml/xgboost-model"}}'),o=t(4848),i=t(8453);let s={},r="Feature: platform admin portal",l={},d=[{value:"A separate login, on purpose",id:"a-separate-login-on-purpose",level:2},{value:"Cross-tenant analytics",id:"cross-tenant-analytics",level:2},{value:"Organization lifecycle",id:"organization-lifecycle",level:2},{value:"Feature flags",id:"feature-flags",level:2},{value:"Feedback triage",id:"feedback-triage",level:2},{value:"Where this sits relative to the rest of the product",id:"where-this-sits-relative-to-the-rest-of-the-product",level:2}];function h(e){let a={a:"a",h1:"h1",h2:"h2",header:"header",mermaid:"mermaid",p:"p",strong:"strong",...(0,i.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(a.header,{children:(0,o.jsx)(a.h1,{id:"feature-platform-admin-portal",children:"Feature: platform admin portal"})}),"\n",(0,o.jsx)(a.p,{children:"Every organization that signs up gets its own isolated workspace \u2014 its own\nusers, sessions, policies, and data. Someone still has to run the platform\nthose workspaces live on: provisioning new organizations, setting quotas,\ntriaging feedback, and controlling which features are available where. The\nplatform admin portal is that control plane, and it is deliberately kept\noutside the multi-tenant application entirely."}),"\n",(0,o.jsx)(a.mermaid,{value:'flowchart TD\n    subgraph Org["Organization app"]\n        OrgUser["org user"] --\x3e|"ds_session cookie"| OrgApp["org-scoped app<br/>(own data only)"]\n    end\n    subgraph Platform["Platform admin portal"]\n        Admin["platform admin"] --\x3e|"ds_platform_session cookie"| Portal["platform portal<br/>(every organization)"]\n    end\n    Portal --\x3e Orgs["Create / suspend / delete orgs,<br/>set seat & session quotas"]\n    Portal --\x3e Flags["Toggle features<br/>globally or per organization"]\n    Portal --\x3e Dash["Cross-tenant analytics \u2014<br/>runs, entities, quota usage"]\n    Portal --\x3e Feedback["Triage bug reports &<br/>feature requests from every org"]\n    OrgApp -.->|"feedback submission"| Feedback'}),"\n",(0,o.jsx)(a.h2,{id:"a-separate-login-on-purpose",children:"A separate login, on purpose"}),"\n",(0,o.jsx)(a.p,{children:"A platform admin is not a member of any organization \u2014 they have no role\nand no organization-scoped permissions, because the concept doesn't apply to\nthem. Signing in to the platform portal uses its own login page and its own\nsession cookie, entirely distinct from an organization user's session. The\ntwo never mix: an organization session cannot open a platform-portal page,\nand a platform session cannot open an organization page. This keeps a\nplatform admin's broad, cross-tenant access structurally separate from the\nper-organization access model everything else in the product uses."}),"\n",(0,o.jsx)(a.h2,{id:"cross-tenant-analytics",children:"Cross-tenant analytics"}),"\n",(0,o.jsx)(a.p,{children:"The org-scoped dashboard inside each organization shows that organization's\nown runs and entities. The platform dashboard shows the same shape of data\nsummed across every organization at once \u2014 total runs, entities\ntransformed, active vs. suspended organizations, quota utilization per\norganization, and which admins and users are generating the most activity.\nIt exists so the platform team can see load, adoption, and support signal\nacross the whole deployment without switching between organizations."}),"\n",(0,o.jsx)(a.h2,{id:"organization-lifecycle",children:"Organization lifecycle"}),"\n",(0,o.jsx)(a.p,{children:"Platform admins create new organizations, set their seat count and\nmonthly-session quotas, and suspend or (soft-)delete one if needed \u2014 a\nsuspended organization's members are locked out immediately, at every route\nand every live connection, not just new sign-ins. Deleting an organization\nis a soft delete: the row is marked gone rather than purged, so its data\nsurvives for recovery or audit rather than vanishing outright."}),"\n",(0,o.jsx)(a.h2,{id:"feature-flags",children:"Feature flags"}),"\n",(0,o.jsx)(a.p,{children:"Not every organization should have access to every capability at once \u2014 a\nfeature might be mid-rollout, reserved for a pricing tier, or disabled while\nan issue is investigated. The platform portal's feature flag console lets\nan admin flip a feature off globally, or leave it on globally but carve out\nan exception for one specific organization (or the reverse \u2014 off globally,\non for one organization)."}),"\n",(0,o.jsxs)(a.p,{children:["Resolution always follows the same order: an organization-specific override\nwins if one exists; otherwise the global setting applies; and a flag the\nsystem doesn't recognize at all is treated as ",(0,o.jsx)(a.strong,{children:"off"}),'. Nothing is\nimplicitly available \u2014 a capability is only reachable if a flag explicitly\nsays so, which matters for a compliance-focused product where the wrong\ndefault is "silently allow," not "silently deny."']}),"\n",(0,o.jsx)(a.h2,{id:"feedback-triage",children:"Feedback triage"}),"\n",(0,o.jsx)(a.p,{children:"Any signed-in organization user can submit a bug report or feature request\nfrom within the app. Every submission lands in one shared queue in the\nplatform portal, tagged with the organization and user it came from, so the\nplatform team triages support signal across all tenants from a single\nplace instead of per-organization channels."}),"\n",(0,o.jsx)(a.h2,{id:"where-this-sits-relative-to-the-rest-of-the-product",children:"Where this sits relative to the rest of the product"}),"\n",(0,o.jsxs)(a.p,{children:["The platform portal is additive \u2014 it doesn't change how an organization's\nown users authenticate, work, or see their data. It's the layer above every\norganization, for the team operating the platform rather than the teams\nusing it. See ",(0,o.jsx)(a.a,{href:"../architecture/auth-and-organizations",children:"Auth & organizations"}),"\nfor how an individual organization's own access model works, and the\n",(0,o.jsx)(a.a,{href:"https://github.com/DataShield-sp18/data-shield/tree/main/.wiki/Engineering/Platform-Admin-Portal.md",children:"Data Shield wiki"}),"\nfor full implementation detail."]})]})}function p(e={}){let{wrapper:a}={...(0,i.R)(),...e.components};return a?(0,o.jsx)(a,{...e,children:(0,o.jsx)(h,{...e})}):h(e)}}}]);